let lang = 'en';
try { lang = localStorage.getItem(KEY) ?? (/^ja\b/i.test(navigator.language ?? '') ? 'ja' : 'en'); } catch { /* storage off */ }
if (lang !== 'ja') lang = 'en';
export const getLang = () => lang;

export function t(s, vars) {
  let r = lang === 'ja' ? (JA[s] ?? s) : s;
  if (vars) r = r.replace(/\{(\w+)\}/g, (m, k) => (vars[k] ?? m));
  return r;
}

// fixed text: translate in place, remembering the English (text nodes and attributes)
const ATTRS = ['title', 'aria-label', 'placeholder'];
const origText = new WeakMap(), origAttr = new WeakMap();
function textNode(n) {
  const raw = n.nodeValue, s = raw.trim(); if (!s) return;
  let en = origText.get(n);
  if (en == null || (s !== en.s && s !== JA[en.s])) { if (!(s in JA)) return; en = { s, raw }; origText.set(n, en); } // new English text
  const want = lang === 'ja' ? en.raw.replace(en.s, JA[en.s]) : en.raw;
  if (raw !== want) n.nodeValue = want;
}
function element(el) {
  let o = origAttr.get(el);
  for (const a of ATTRS) {
    const v = el.getAttribute(a); if (v == null) continue;
    if (!o?.[a] || (v !== o[a] && v !== JA[o[a]])) { if (!(v in JA)) continue; o ??= {}; o[a] = v; origAttr.set(el, o); }
    const want = lang === 'ja' ? JA[o[a]] : o[a];
    if (v !== want) el.setAttribute(a, want);
  }
}
function walk(root) {
  if (root.nodeType === 3) { textNode(root); return; }
  if (root.nodeType !== 1 || root.tagName === 'SCRIPT' || root.tagName === 'STYLE' || root.closest?.('.maplibregl-ctrl-attrib, svg text.no-i18n')) return;
  element(root);
  const it = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT);
  for (let n = it.nextNode(); n; n = it.nextNode()) (n.nodeType === 3 ? textNode(n) : element(n));
}
// options of a <select>: text nodes too
const observer = new MutationObserver((list) => {
  for (const m of list) {
    if (m.type === 'characterData') textNode(m.target);
    else if (m.type === 'attributes') element(m.target);
    else for (const n of m.addedNodes) walk(n);
  }
});
const listeners = [];
export const onLangChange = (fn) => listeners.push(fn);
export function startI18n() {
  document.documentElement.lang = lang;
  walk(document.body);
  observer.observe(document.body, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ATTRS });
}
export function setLang(l) {
  lang = l === 'ja' ? 'ja' : 'en';
  try { localStorage.setItem(KEY, lang); } catch { /* storage off */ }
  document.documentElement.lang = lang;
  walk(document.body);
  for (const fn of listeners) fn(lang);
}
