// Personal road notes: "avoid" or "prefer" a road, from riding it. No map data says a footway is too narrow or a
// back lane is a great shortcut; the rider knows after one ride. A note is the road's shape (the graph chain tapped),
// kept in this browser's localStorage ('cyclescape.notes.v1'); the live graph is rebuilt from tiles every time, so a
// note is re-attached on each build: a road piece (atom) takes the note's factor when its midpoint lies within
// MATCH_M of the note's line and runs within MATCH_DEG of its direction.
export const NOTE_FACTOR = { avoid: 5, prefer: 0.8 };
const KEY = 'cyclescape.notes.v1', MATCH_M = 12, MATCH_DEG = 30;

export function listNotes() { try { const v = JSON.parse(localStorage.getItem(KEY) ?? '[]'); return Array.isArray(v) ? v : []; } catch { return []; } }
function write(list) { try { localStorage.setItem(KEY, JSON.stringify(list)); return true; } catch { return false; } }
export function addNote(kind, coords, label) {
  const n = { id: `n${Date.now().toString(36)}${Math.random().toString(36).slice(2, 5)}`, kind, coords: coords.map(([x, y]) => [+x.toFixed(6), +y.toFixed(6)]), label: label ?? null, created: new Date().toISOString() };
  return write([...listNotes(), n]) ? n : null;
}
export function removeNote(id) { return write(listNotes().filter((n) => n.id !== id)); }

// notes overlapping a line (the tapped chain): the ones its midpoint matches
export function notesOn(coords, notes = listNotes()) {
  const mid = coords[coords.length >> 1];
  return notes.filter((n) => distToLine(mid, n.coords) <= MATCH_M * 2);
}

const kxAt = (lat) => Math.cos((lat * Math.PI) / 180) * 111320, KY = 110574;
function distToLine([px, py], line) {
  const kx = kxAt(py); let best = Infinity;
  for (let i = 1; i < line.length; i++) {
    const ax = (line[i - 1][0] - px) * kx, ay = (line[i - 1][1] - py) * KY, bx = (line[i][0] - px) * kx, by = (line[i][1] - py) * KY;
    const dx = bx - ax, dy = by - ay, l2 = dx * dx + dy * dy || 1, u = Math.max(0, Math.min(1, -(ax * dx + ay * dy) / l2));
    best = Math.min(best, Math.hypot(ax + u * dx, ay + u * dy));
  }
  return best;
}
// heading (deg, 0..180: direction-free) of a line near a point
function headingNear([px, py], line) {
  const kx = kxAt(py); let best = Infinity, h = 0;
  for (let i = 1; i < line.length; i++) {
    const mx = ((line[i - 1][0] + line[i][0]) / 2 - px) * kx, my = ((line[i - 1][1] + line[i][1]) / 2 - py) * KY, d = Math.hypot(mx, my);
    if (d < best) { best = d; h = (Math.atan2((line[i][0] - line[i - 1][0]) * kx, (line[i][1] - line[i - 1][1]) * KY) * 180) / Math.PI; }
  }
  return ((h % 180) + 180) % 180;
}

// per-atom factor for a graph (Float32Array, 0 = no note), or null when there are no notes near it
export function noteFactors(graph, chainCoords, notes = listNotes()) {
  if (!notes.length || !graph?.nChains) return null;
  const pad = 0.0005, boxes = notes.map((n) => { const xs = n.coords.map((c) => c[0]), ys = n.coords.map((c) => c[1]); return [Math.min(...xs) - pad, Math.min(...ys) - pad, Math.max(...xs) + pad, Math.max(...ys) + pad]; });
  const out = new Float32Array(graph.nAtoms); let any = false;
  for (let c = 0; c < graph.nChains; c++) {
    // cheap reject: the chain's first and last node outside every note box
    const s = graph.coordStart[c], e = graph.coordStart[c + 1] - 1;
    const near = boxes.some(([x0, y0, x1, y1]) => [s, e].some((k) => graph.coordLon[k] >= x0 && graph.coordLon[k] <= x1 && graph.coordLat[k] >= y0 && graph.coordLat[k] <= y1));
    if (!near) continue;
    const cs = chainCoords(graph, c), cum = [0];
    for (let q = 1; q < cs.length; q++) cum.push(cum[q - 1] + Math.hypot((cs[q][0] - cs[q - 1][0]) * kxAt(cs[q][1]), (cs[q][1] - cs[q - 1][1]) * KY));
    let La = 0; for (let i = graph.atomStart[c]; i < graph.atomStart[c + 1]; i++) La += graph.atomLen[i];
    let d = 0;
    for (let i = graph.atomStart[c]; i < graph.atomStart[c + 1]; i++) {
      const m = ((d + graph.atomLen[i] / 2) * cum.at(-1)) / (La || 1); let q = 1; while (q < cum.length - 1 && cum[q] < m) q++;
      const f = cum[q] > cum[q - 1] ? (m - cum[q - 1]) / (cum[q] - cum[q - 1]) : 0;
      const p = [cs[q - 1][0] + f * (cs[q][0] - cs[q - 1][0]), cs[q - 1][1] + f * (cs[q][1] - cs[q - 1][1])];
      const h = headingNear(p, cs);
      for (const n of notes) {
        if (distToLine(p, n.coords) > MATCH_M) continue;
        const dh = Math.abs(h - headingNear(p, n.coords)); if (Math.min(dh, 180 - dh) > MATCH_DEG) continue;
        out[i] = NOTE_FACTOR[n.kind] ?? 1; any = true;
      }
      d += graph.atomLen[i];
    }
  }
  return any ? out : null;
}
