// Basemap styles. MapTiler keys are public in the browser by design; restrict this one to your
// domains in the MapTiler dashboard. Keep this file out of git if you prefer.
import { gsiPaleHillshade } from './gsi-pale.mjs';
import { RRIM_WHITE_TILES } from './rrim-white.mjs';

export const MAPTILER_KEY = 'VK9en7fqcN8VTzfv5LVe';
const mt = (id) => `https://api.maptiler.com/maps/${id}/style.json?key=${MAPTILER_KEY}`;
const GSIV = 'https://gsi-cyberjapan.github.io/gsivectortile-mapbox-gl-js/';
const GSI_ATTR = '<a href="https://maps.gsi.go.jp/development/ichiran.html">地理院タイル</a>';
// 3D terrain DEMs (app.mjs addTerrain); a style picks one with `terrain: '<key>'`, default 'maptiler'
export const TERRAINS = {
  maptiler: { exaggeration: 1.5, source: { type: 'raster-dem', url: `https://api.maptiler.com/tiles/terrain-rgb-v2/tiles.json?key=${MAPTILER_KEY}` } },
  // AIST シームレス標高タイル 陸域統合DEM as Terrain-RGB (GSI DEM5/DEM10B, lidar where available): 5 m detail to z15
  // everywhere (deeper tiles exist only in lidar areas and error elsewhere, so MapLibre overzooms z15)
  aist: { exaggeration: 1, source: { type: 'raster-dem', tiles: ['https://gbank.gsj.jp/seamless/elev/terrainRGB/land/{z}/{y}/{x}.png'], tileSize: 256, maxzoom: 15,
    attribution: '<a href="https://tiles.gsj.jp/tiles/elev/tiles.html">産総研 シームレス標高タイル（陸域統合DEM）</a>' } },
};
export const DEFAULT_STYLE = 'Outdoor'; // first visit; afterwards the last choice (localStorage 'cyclescape.basemap')
export const STYLES = [
  { title: 'Satellite Hybrid', uri: mt('hybrid') },
  { title: 'Streets', uri: mt('streets') },
  { title: 'Bright', uri: mt('bright') },
  { title: 'Outdoor', uri: mt('outdoor') },
  {
    // 赤色立体地図ハイブリッド全国版 (Hybrid Red Relief Image Map, all Japan), public ArcGIS tile service by Asia Air Survey.
    // Web Mercator, z0-15 (overzoomed beyond). No explicit licence on the item: fine for personal viewing; check
    // Asia Air Survey's terms before publishing it on a public site.
    title: 'Red relief (RRIM)',
    paleOverlay: true, // offers 'GSI Pale on top (multiply)' (app.mjs paleOverlay)
    uri: {
      version: 8,
      sources: {
        rrim: { type: 'raster', tiles: [RRIM_WHITE_TILES], // rrim-white.mjs: Asia Air Survey's tiles with the grey flats re-levelled to white
          tileSize: 256, maxzoom: 15, attribution: '赤色立体地図 © <a href="https://www.rrim.jp/">アジア航測株式会社</a>' },
      },
      layers: [
        { id: 'bg', type: 'background', paint: { 'background-color': '#1a1a1a' } },
        { id: 'rrim', type: 'raster', source: 'rrim' },
      ],
    },
  },
  // GSI vector maps (国土地理院ベクトルタイル), the experimental_bvmap tiles the live road graph reads. 淡色+陰影 is GSI's
  // own design as drawn on maps.gsi.go.jp/vector (snapshot + DEM/icons: gsi-pale.mjs); 写真+注記 puts the 標準 labels
  // (GSI's Mapbox style file) over the seamless photo. Both are built when first chosen.
  gsiPaleHillshade('GSI 淡色+陰影 (pale + shading)'),
  { title: 'GSI 写真+注記 (photo + labels)', terrain: 'aist', build: async () => {
    const s = await fetch(`${GSIV}std.json`).then((r) => r.json());
    return { version: 8, glyphs: s.glyphs, sprite: s.sprite,
      sources: { photo: { type: 'raster', tiles: ['https://cyberjapandata.gsi.go.jp/xyz/seamlessphoto/{z}/{x}/{y}.jpg'], tileSize: 256, maxzoom: 18, attribution: GSI_ATTR }, ...s.sources },
      layers: [{ id: 'photo', type: 'raster', source: 'photo' }, ...s.layers.filter((l) => l.type === 'symbol')] };
  } },
  {
    title: 'GSI dark',
    uri: {
      version: 8,
      sources: {
        pale: { type: 'raster', tiles: ['https://cyberjapandata.gsi.go.jp/xyz/pale/{z}/{x}/{y}.png'], tileSize: 256, maxzoom: 18,
          attribution: '<a href="https://maps.gsi.go.jp/development/ichiran.html">地理院タイル</a>' },
        hill: { type: 'raster', tiles: ['https://cyberjapandata.gsi.go.jp/xyz/hillshademap/{z}/{x}/{y}.png'], tileSize: 256, maxzoom: 16 },
      },
      layers: [
        { id: 'bg', type: 'background', paint: { 'background-color': '#0b0b0e' } },
        { id: 'pale', type: 'raster', source: 'pale', paint: { 'raster-brightness-max': 0.32, 'raster-saturation': -1, 'raster-contrast': 0.1 } },
        { id: 'hill', type: 'raster', source: 'hill', paint: { 'raster-opacity': 0.18 } },
      ],
    },
  },
];

