// Red relief (RRIM), re-levelled to white. In red relief, flat ground is mid grey (about #a8a8a8: lightness 160-176
// in Asia Air Survey's tiles), which greys the whole map and, under the GSI Pale multiply overlay, leaves labels dark
// grey on grey. rrimw://{z}/{y}/{x} serves the same tiles with the white point moved to that grey (every channel x
// WHITE_GAIN, clipped): flat ground turns white, red slopes keep their hue, and valleys stay dark. The basemap always
// uses these tiles.
export const RRIM_TILES = 'https://tiles.arcgis.com/tiles/kgiERDTtzXuaAvgI/arcgis/rest/services/All_Japan/MapServer/tile/{z}/{y}/{x}';
export const RRIM_WHITE_TILES = 'rrimw://{z}/{y}/{x}';
const WHITE_GAIN = 255 / 172;

let registered = false;
export function registerRrimWhite() {
  if (registered) return; registered = true;
  const lut = new Uint8ClampedArray(256); for (let v = 0; v < 256; v++) lut[v] = Math.round(v * WHITE_GAIN);
  maplibregl.addProtocol('rrimw', async (params, abort) => {
    const [z, y, x] = params.url.replace('rrimw://', '').split('/');
    const res = await fetch(RRIM_TILES.replace('{z}', z).replace('{y}', y).replace('{x}', x), { signal: abort.signal });
    if (!res.ok) throw new Error(`RRIM HTTP ${res.status}`);
    const bmp = await createImageBitmap(await res.blob());
    const c = new OffscreenCanvas(bmp.width, bmp.height), ctx = c.getContext('2d', { willReadFrequently: true });
    ctx.drawImage(bmp, 0, 0); bmp.close();
    const img = ctx.getImageData(0, 0, c.width, c.height), px = img.data;
    for (let i = 0; i < px.length; i += 4) { px[i] = lut[px[i]]; px[i + 1] = lut[px[i + 1]]; px[i + 2] = lut[px[i + 2]]; }
    ctx.putImageData(img, 0, 0);
    return { data: await (await c.convertToBlob({ type: 'image/jpeg', quality: 0.9 })).arrayBuffer() };
  });
}
