// Place search and names for the route planner, from GSI (国土地理院), the same public source as the road and
// elevation tiles: no key, CORS open. Queries go to GSI as typed.
//   search(q, near)  地名検索 (msearch.gsi.go.jp): place names, stations, addresses. GSI returns them unranked (東京駅
//                    came after 北海道東神楽町東), so they are ranked here: exact name, then names starting with or
//                    containing the query, then by distance from `near` ([lon, lat]).
//   placeName(ll)    逆ジオコーダ (mreversegeocoder.gsi.go.jp): municipality + town, e.g. "一関市 千厩町磐清水"; the
//                    municipality names come from GSI's muni.js table, fetched once.
const SEARCH = 'https://msearch.gsi.go.jp/address-search/AddressSearch?q=';
const REVERSE = 'https://mreversegeocoder.gsi.go.jp/reverse-geocoder/LonLatToAddress';
const MUNI = 'https://maps.gsi.go.jp/js/muni.js';

const km = (a, b) => { const kx = Math.cos(((a[1] + b[1]) / 2) * Math.PI / 180) * 111.32; return Math.hypot((a[0] - b[0]) * kx, (a[1] - b[1]) * 110.574); };
const norm = (s) => String(s).normalize('NFKC').replace(/\s+/g, '');

export function rank(results, q, near, limit = 8) {
  const nq = norm(q);
  const score = (t) => { const n = norm(t); return n === nq ? 0 : n.endsWith(nq) && n.length - nq.length <= 4 ? 1 : n.startsWith(nq) ? 2 : n.includes(nq) ? 3 : 4; };
  const seen = new Set();
  return results
    .map((f) => ({ title: f.properties?.title ?? '', ll: f.geometry?.coordinates }))
    .filter((r) => r.title && Array.isArray(r.ll) && r.ll.length >= 2)
    .map((r) => ({ ...r, s: score(r.title), d: near ? km(r.ll, near) : 0 }))
    .sort((a, b) => a.s - b.s || a.title.length - b.title.length || a.d - b.d) // same kind of match: the plainer (shorter) name, then the nearer
    .filter((r) => { const k = `${r.title}|${r.ll[0].toFixed(3)},${r.ll[1].toFixed(3)}`; if (seen.has(k)) return false; seen.add(k); return true; })
    .slice(0, limit);
}

export async function search(q, near, signal) {
  const t = String(q).trim(); if (t.length < 1) return [];
  const res = await fetch(SEARCH + encodeURIComponent(t), { signal });
  if (!res.ok) throw new Error(`GSI search HTTP ${res.status}`);
  return rank(await res.json(), t, near);
}

let muniPromise = null;
function muni() {
  muniPromise ??= fetch(MUNI).then((r) => r.text()).then((js) => {
    const m = new Map(); // "03209" -> "一関市"
    for (const x of js.matchAll(/=\s*'([^']*)'/g)) { const f = x[1].split(','); if (f.length >= 4) m.set(f[2].padStart(5, '0'), f[3].replace(/　/g, ' ')); }
    return m;
  }).catch(() => new Map());
  return muniPromise;
}
export async function placeName([lon, lat]) {
  try {
    const r = await fetch(`${REVERSE}?lat=${lat.toFixed(6)}&lon=${lon.toFixed(6)}`).then((x) => x.json());
    const cd = r?.results?.muniCd, town = r?.results?.lv01Nm;
    if (!cd && !town) return null;
    const city = cd ? (await muni()).get(String(cd).padStart(5, '0')) : null;
    return [city, town && town !== '－' ? town : null].filter(Boolean).join(' ') || null;
  } catch { return null; }
}
